bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import pg from 'pg';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
setDefaultResultOrder('ipv4first');
setDefaultAutoSelectFamily(false);
const e=process.env;
const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 database:e.VIDEOBOT_DB_NAME,
 password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 connectionTimeoutMillis:5000,max:1});
const egress=createCreatorTelegramFetch(globalThis.fetch);
try {
 const pending=await pool.query("SELECT COUNT(*)::integer AS n FROM videobot_creator_sessions WHERE state ? 'stickerPending' AND state->'stickerPending'->>'status' IN ('needs_reconcile','in_progress')");
 const first=await pool.query("SELECT pack_name FROM videobot_sticker_packs WHERE status='active' ORDER BY pack_name LIMIT 1");
 const api=createTelegramBotApi({token,fetchImpl:egress.fetch,timeoutMs:25000});
 const bot=await api('getMe',{});
 if(bot?.is_bot!==true)throw Error('STK01_REAL_BOT_IDENTITY_INVALID');
 console.log('STK01_REAL_TELEGRAM_BOT_READONLY=PASS');
 console.log('STK01_RECOVERY_PENDING_COUNT='+Number(pending.rows[0].n));
 if(first.rows.length){
   const set=await api('getStickerSet',{name:first.rows[0].pack_name});
   if(!set||set.name!==first.rows[0].pack_name||!Array.isArray(set.stickers))
     throw Error('STK01_LIVE_PACK_READBACK_MISMATCH');
   console.log('STK01_REAL_TELEGRAM_PACK_READBACK=PASS');
   console.log('STK01_REAL_TELEGRAM_PACK_ITEMS='+set.stickers.length);
 }else console.log('STK01_REAL_TELEGRAM_PACK_READBACK=NO_REGISTERED_PACK');
}catch(e){
 console.log('STK01_REAL_TELEGRAM_READBACK=FAIL');
 process.exitCode=1;
}finally{await pool.end();await egress.close();}
NODE
echo STK01_READONLY_REAL_E2E_COMPLETE=PASS
